// Demo sub-workflow: derives a few fields from whatever the caller sent.
// Zero credentials and no outbound calls — it exists so a fresh install has
// a real sub-workflow edge on the architecture map rather than an empty
// column, and so the caller has something to hand work to.
return items.map((item) => {
  const rec = item.json || {};
  const email = String(rec.email || '');
  return {
    json: {
      ...rec,
      domain: email.includes('@') ? email.split('@').pop() : null,
      received_at: new Date().toISOString(),
      priority: Number(rec.amount || 0) > 500 ? 'high' : 'normal',
    },
  };
});
